+extern "C" void scan_and_histogram(const int64_t* __restrict in, int64_t* __restrict out, size_t n, uint64_t* __restrict hist) {
+    constexpr int SUB = 8;
+    constexpr size_t PREFETCH_BYTES = 256;
+
+    uint32_t sub[SUB][256] = {};
+
+    if (n == 0) {
+        for (int b = 0; b < 256; ++b) hist[b] = 0;
+        return;
+    }
+
+    int64_t s0 = 0, s1 = 0;
+    size_t i = 0;
+
+    for (; i + 8 <= n; i += 8) {
+        if (PREFETCH_BYTES > 0) {
+            __builtin_prefetch(in + i + PREFETCH_BYTES / 8, 0, 3);
+            __builtin_prefetch(out + i + PREFETCH_BYTES / 8, 1, 3);
+        }
+
+        int64_t v0 = in[i],   v1 = in[i + 1];
+        int64_t v2 = in[i + 2], v3 = in[i + 3];
+        int64_t v4 = in[i + 4], v5 = in[i + 5];
+        int64_t v6 = in[i + 6], v7 = in[i + 7];
+
+        // Two independent prefix-sum chains: even indices -> s0, odd indices -> s1
+        int64_t s1_old = s1;
+        s0 += v0; out[i]     = s0 + s1_old;
+        s1 += v1; out[i + 1] = s0 + s1;
+
+        s1_old = s1;
+        s0 += v2; out[i + 2] = s0 + s1_old;
+        s1 += v3; out[i + 3] = s0 + s1;
+
+        s1_old = s1;
+        s0 += v4; out[i + 4] = s0 + s1_old;
+        s1 += v5; out[i + 5] = s0 + s1;
+
+        s1_old = s1;
+        s0 += v6; out[i + 6] = s0 + s1_old;
+        s1 += v7; out[i + 7] = s0 + s1;
+
+        // Sub-histogram index = position within the 8-element block
+        sub[0][(unsigned)(v0 & 255)]++;
+        sub[1][(unsigned)(v1 & 255)]++;
+        sub[2][(unsigned)(v2 & 255)]++;
+        sub[3][(unsigned)(v3 & 255)]++;
+        sub[4][(unsigned)(v4 & 255)]++;
+        sub[5][(unsigned)(v5 & 255)]++;
+        sub[6][(unsigned)(v6 & 255)]++;
+        sub[7][(unsigned)(v7 & 255)]++;
+    }
+
+    int64_t sum = s0 + s1;
+    for (; i < n; ++i) {
+        int64_t v = in[i];
+        sum += v;
         out[i] = sum;
-        hist[in[i] & 255]++;
+        sub[i & (SUB - 1)][(unsigned)(v & 255)]++;
+    }
+
+    for (int b = 0; b < 256; ++b) {
+        hist[b] = (uint64_t)sub[0][b] + sub[1][b] + sub[2][b] + sub[3][b] +
+                  sub[4][b] + sub[5][b] + sub[6][b] + sub[7][b];
     }
 }
